// The named role sets. Membership is the question every caller actually
// asks — `DRIVABLE` excludes the malecón on purpose (a promenade is
// somewhere people walk), and `CALLE` excludes a muelle deck because a
// deck is something you drive ON, not a street to link TO.
export const SURFACE_ROLE = Object.freeze({
  DRIVABLE: Object.freeze([SURFACE.ROAD, SURFACE.PASEO, SURFACE.BRIDGE, SURFACE.BEACH, SURFACE.BOULEVARD, SURFACE.BARRO, SURFACE.GRAVEL]),
  WALL: Object.freeze([SURFACE.LAND, SURFACE.ACERA]),
  STREET: Object.freeze([SURFACE.ROAD, SURFACE.PASEO, SURFACE.BRIDGE, SURFACE.ACERA, SURFACE.BOULEVARD, SURFACE.BARRO, SURFACE.GRAVEL, SURFACE.MALECON]),
  CARRIAGEWAY: Object.freeze([SURFACE.ROAD, SURFACE.PASEO, SURFACE.BRIDGE, SURFACE.BARRO, SURFACE.GRAVEL]),
  CALLE: Object.freeze([SURFACE.ROAD, SURFACE.PASEO, SURFACE.BARRO, SURFACE.GRAVEL]),
});

/** Does `cls` (a wire id) belong to the named role set? */
export function hasSurfaceRole(role, cls) {
  const members = SURFACE_ROLE[role];
  return members !== undefined && members.includes(cls);
}

